import { readFileSync } from 'fs';
import { fileURLToPath } from 'url';
import { dirname, join } from 'path';

const __filename = fileURLToPath(import.meta.url);
const __dirname = dirname(__filename);

function testLicenseNotice() {
  try {
    const licenseContent = readFileSync(join(__dirname, 'license-notice.txt'), 'utf8');

    // Test 1: Check that MERCHANTABLITY is NOT present
    if (licenseContent.includes('MERCHANTABLITY')) {
      console.error('FAIL: License still contains typo MERCHANTABLITY');
      return false;
    }

    // Test 2: Check that MERCHANTABILITY IS present
    if (!licenseContent.includes('MERCHANTABILITY')) {
      console.error('FAIL: License does not contain corrected term MERCHANTABILITY');
      return false;
    }

    // Test 3: Check the exact line format
    const lines = licenseContent.split('\n');
    const warrantyLine = lines.find(line => line.includes('MERCHANTABILITY'));

    if (!warrantyLine) {
      console.error('FAIL: Could not find warranty line with MERCHANTABILITY');
      return false;
    }

    const expectedLine = 'WARRANTIES OR CONDITIONS OF TITLE, FITNESS FOR A PARTICULAR PURPOSE,';
    const nextLine = lines[lines.indexOf(warrantyLine) - 1];

    if (nextLine !== expectedLine) {
      console.error('FAIL: License formatting is incorrect');
      return false;
    }

    console.log('PASS: All license tests passed');
    return true;

  } catch (error) {
    console.error('FAIL: Error reading license file:', error.message);
    return false;
  }
}

// Run the test
if (testLicenseNotice()) {
  process.exit(0);
} else {
  process.exit(1);
}
